from __future__ import annotations
import copy
from .model import validate

CASE_TYPES = ("Dead", "Live", "Roof Live", "Wind", "Seismic", "Other")
COMBINATION_METHODS = ("LRFD", "ASD", "Service", "Custom")


def guess_case_type(case_id: str) -> str:
    key = (case_id or "").strip().upper()
    if key.startswith("DL") or key in {"D", "DEAD", "SW"}:
        return "Dead"
    if key.startswith("LL") or key in {"L", "LIVE"}:
        return "Live"
    if key.startswith("RL") or "ROOF" in key:
        return "Roof Live"
    if key.startswith("W"):
        return "Wind"
    if key.startswith("E") or key.startswith("EQ") or "SEISM" in key:
        return "Seismic"
    return "Other"


def metadata_for_cases(model: dict) -> dict:
    stored = model.get("case_metadata", {}) or {}
    out = {}
    for case in model.get("cases", []):
        row = stored.get(case, {}) if isinstance(stored, dict) else {}
        out[case] = {
            "type": row.get("type") or guess_case_type(case),
            "description": row.get("description", ""),
        }
    return out


def combination_metadata(model: dict) -> dict:
    stored = model.get("combination_metadata", {}) or {}
    return {
        name: {"method": (stored.get(name, {}) or {}).get("method", "Custom")}
        for name in (model.get("combinations", {}) or {})
    }


def apply_load_case_configuration(
    model: dict,
    *,
    cases: list[str],
    case_metadata: dict,
    combinations: dict,
    combination_meta: dict,
    self_weight: bool,
    self_weight_case: str | None,
) -> dict:
    cases = [str(case).strip() for case in cases if str(case).strip()]
    if not cases:
        raise ValueError("At least one load case is required")
    if len(cases) != len(set(cases)):
        raise ValueError("Load Case IDs must be unique")

    referenced = {
        row.get("case")
        for field in ("point_loads", "distributed_loads")
        for row in model.get(field, [])
        if row.get("case")
    }
    missing = sorted(referenced - set(cases))
    if missing:
        raise ValueError(
            "Cannot remove load case(s) still used by loads: " + ", ".join(missing)
        )

    if self_weight and self_weight_case not in cases:
        raise ValueError("Select a valid Self-weight case")

    cleaned_combinations = {}
    cleaned_combo_meta = {}
    for name, factors in combinations.items():
        name = str(name).strip()
        if not name:
            continue
        row = {}
        for case in cases:
            value = float((factors or {}).get(case, 0.0))
            if value:
                row[case] = value
        if not row:
            raise ValueError(f"Combination {name}: enter at least one non-zero factor")
        cleaned_combinations[name] = row
        method = (combination_meta.get(name, {}) or {}).get("method", "Custom")
        cleaned_combo_meta[name] = {"method": method if method in COMBINATION_METHODS else "Custom"}

    out = copy.deepcopy(model)
    out["cases"] = cases
    out["case_metadata"] = {
        case: {
            "type": (case_metadata.get(case, {}) or {}).get("type", guess_case_type(case)),
            "description": (case_metadata.get(case, {}) or {}).get("description", ""),
        }
        for case in cases
    }
    out["combinations"] = cleaned_combinations
    out["combination_metadata"] = cleaned_combo_meta
    out["self_weight"] = bool(self_weight)
    out["self_weight_case"] = self_weight_case if self_weight else (self_weight_case if self_weight_case in cases else cases[0])
    return validate(out)

"""Solver-independent JSON model for 2D XZ structural analysis."""
from __future__ import annotations
import copy
import hashlib
import json
import math
from .constants import MEMBER_TYPES, SCHEMA_VERSION, SPRING_DOF, SUPPORTS


class ModelError(ValueError):
    pass


def _finite(value, label, *, positive=False):
    if isinstance(value, bool) or not isinstance(value, (int, float)) or not math.isfinite(value):
        raise ModelError(f"{label}: expected finite number")
    if positive and value <= 0:
        raise ModelError(f"{label}: expected positive number")


def member_length(model: dict, member: dict) -> float:
    nodes = {row["id"]: row for row in model["nodes"]}
    a, b = nodes[member["i"]], nodes[member["j"]]
    return math.hypot(b["x"] - a["x"], b["z"] - a["z"])


def validate(data: dict) -> dict:
    try:
        model = json.loads(json.dumps(data, allow_nan=False))
    except (TypeError, ValueError) as exc:
        raise ModelError(f"Model must be JSON-safe: {exc}") from exc
    if not isinstance(model, dict) or model.get("schema") != SCHEMA_VERSION:
        raise ModelError(f"Unsupported schema; expected {SCHEMA_VERSION}")

    required = ("nodes", "members", "materials", "sections", "cases")
    for name in required:
        if name not in model or not isinstance(model[name], list):
            raise ModelError(f"Missing/invalid {name}")

    registries = {}
    for name in ("nodes", "members", "materials", "sections"):
        rows = model[name]
        ids = [row.get("id") for row in rows]
        if any(not isinstance(v, str) or not v.strip() for v in ids) or len(ids) != len(set(ids)):
            raise ModelError(f"{name}: duplicate/invalid IDs")
        registries[name] = {row["id"]: row for row in rows}
    if len(model["nodes"]) < 2 or not model["members"]:
        raise ModelError("At least two nodes and one member are required")

    positions = set()
    for node in model["nodes"]:
        _finite(node.get("x"), f"{node['id']}.x")
        _finite(node.get("z"), f"{node['id']}.z")
        pos = (node["x"], node["z"])
        if pos in positions:
            raise ModelError("Coincident nodes are not allowed")
        positions.add(pos)
        support = node.get("support", "Free")
        if support not in SUPPORTS:
            raise ModelError(f"Unknown support: {support}")
        springs = node.get("springs", {}) or {}
        if not isinstance(springs, dict):
            raise ModelError(f"{node['id']}.springs must be an object")
        if springs and support not in ("Free", "Spring"):
            raise ModelError("Use support Free/Spring when assigning nodal springs")
        for dof, stiffness in springs.items():
            if dof not in SPRING_DOF:
                raise ModelError(f"Unsupported 2D spring DOF: {dof}")
            _finite(stiffness, f"{node['id']}.springs.{dof}", positive=True)

    for material in model["materials"]:
        _finite(material.get("E"), f"{material['id']}.E", positive=True)
        _finite(material.get("rho", 0.0), f"{material['id']}.rho")
        if material.get("rho", 0.0) < 0:
            raise ModelError("rho cannot be negative")

    for section in model["sections"]:
        _finite(section.get("A"), f"{section['id']}.A", positive=True)
        _finite(section.get("Iz"), f"{section['id']}.Iz", positive=True)

    lengths = {}
    for member in model["members"]:
        if member.get("type", "Frame") not in MEMBER_TYPES:
            raise ModelError(f"Unknown member type: {member.get('type')}")
        if member.get("i") not in registries["nodes"] or member.get("j") not in registries["nodes"]:
            raise ModelError(f"{member['id']}: missing node reference")
        if member.get("material") not in registries["materials"]:
            raise ModelError(f"{member['id']}: missing material")
        if member.get("section") not in registries["sections"]:
            raise ModelError(f"{member['id']}: missing section")
        for key in ("release_i", "release_j"):
            if key in member and not isinstance(member[key], bool):
                raise ModelError(f"{member['id']}.{key} must be boolean")
        length = member_length(model, member)
        if length < 1e-9:
            raise ModelError("Zero-length member")
        lengths[member["id"]] = length

    cases = model["cases"]
    if not cases or len(cases) != len(set(cases)) or any(not isinstance(v, str) or not v.strip() for v in cases):
        raise ModelError("Invalid load cases")
    case_metadata = model.get("case_metadata", {}) or {}
    if not isinstance(case_metadata, dict):
        raise ModelError("case_metadata must be an object")
    for case, metadata in case_metadata.items():
        if case not in cases or not isinstance(metadata, dict):
            raise ModelError("Invalid case_metadata")
        if metadata.get("type") is not None and not isinstance(metadata.get("type"), str):
            raise ModelError(f"case_metadata {case}.type must be text")
        if metadata.get("description") is not None and not isinstance(metadata.get("description"), str):
            raise ModelError(f"case_metadata {case}.description must be text")

    combinations = model.get("combinations", {}) or {}
    if not isinstance(combinations, dict):
        raise ModelError("combinations must be an object")
    for name, factors in combinations.items():
        if not isinstance(name, str) or not name or not isinstance(factors, dict) or not factors:
            raise ModelError("Invalid load combination")
        for case, factor in factors.items():
            if case not in cases:
                raise ModelError(f"Combination {name}: unknown case {case}")
            _finite(factor, f"Combination {name}.{case}")

    combination_metadata = model.get("combination_metadata", {}) or {}
    if not isinstance(combination_metadata, dict):
        raise ModelError("combination_metadata must be an object")
    for name, metadata in combination_metadata.items():
        if name not in combinations or not isinstance(metadata, dict):
            raise ModelError("Invalid combination_metadata")
        if metadata.get("method") is not None and not isinstance(metadata.get("method"), str):
            raise ModelError(f"combination_metadata {name}.method must be text")

    for load in model.get("point_loads", []):
        if ("node" in load) == ("member" in load):
            raise ModelError("Point load needs exactly one node or member target")
        if load.get("case") not in cases:
            raise ModelError("Point load has unknown case")
        if load.get("direction") not in ("FX", "FZ", "MY"):
            raise ModelError("Point load direction must be FX/FZ/MY")
        _finite(load.get("value"), "point load value")
        if "node" in load:
            if load["node"] not in registries["nodes"]:
                raise ModelError("Point load has unknown node")
        else:
            if load["member"] not in registries["members"]:
                raise ModelError("Point load has unknown member")
            _finite(load.get("x"), "point load x")
            if not 0 <= load["x"] <= lengths[load["member"]]:
                raise ModelError("Point load is outside member")
            if registries["members"][load["member"]].get("type") == "Truss":
                raise ModelError("Apply truss loads at nodes")

    for load in model.get("distributed_loads", []):
        if load.get("member") not in registries["members"]:
            raise ModelError("Distributed load has unknown member")
        if load.get("case") not in cases or load.get("direction") not in ("FX", "FZ"):
            raise ModelError("Invalid distributed load case/direction")
        if registries["members"][load["member"]].get("type") == "Truss":
            raise ModelError("Apply truss loads at nodes")
        length = lengths[load["member"]]
        x1, x2 = load.get("x1", 0.0), load.get("x2", length)
        for key, value in (("w1", load.get("w1")), ("w2", load.get("w2")), ("x1", x1), ("x2", x2)):
            _finite(value, key)
        if not 0 <= x1 < x2 <= length:
            raise ModelError("Invalid distributed load extent")

    self_weight = model.get("self_weight", False)
    if not isinstance(self_weight, bool):
        raise ModelError("self_weight must be boolean")
    if self_weight:
        sw_case = model.get("self_weight_case")
        if sw_case is not None and sw_case not in cases:
            raise ModelError("Unknown self_weight_case")

    return model


def copy_model(data: dict) -> dict:
    return copy.deepcopy(validate(data))


def fingerprint(model: dict) -> str:
    checked = validate(model)
    raw = json.dumps(checked, sort_keys=True, separators=(",", ":"), allow_nan=False).encode("utf-8")
    return hashlib.sha256(raw).hexdigest()

from __future__ import annotations
import math
import numpy as np
from PySide6.QtCore import QPointF, QRectF, Qt
from PySide6.QtGui import QColor, QPen, QBrush, QPainterPath, QPolygonF
from .diagram_utils import sample_plot, signed_interval_parts
from .label_layout import LabelLayout


class OverlayRenderer:
    """Native IngeTrazo 2D overlay.

    Engineering/result geometry is cached in world coordinates. Camera motion only
    projects cached points and paints them; it never runs anaStruct or rebuilds meshes.
    """

    def __init__(self, panel):
        self.panel = panel
        self._key = None
        self._cache = None
        self._labels = LabelLayout()

    def invalidate(self):
        self._key = None
        self._cache = None

    def _span(self, model):
        xs = [n["x"] for n in model["nodes"]]
        zs = [n["z"] for n in model["nodes"]]
        return max(max(xs) - min(xs), max(zs) - min(zs), 1.0)

    def _frame_y(self):
        return float(getattr(self.panel, "frame_y", 0.0))

    def _world_point(self, member, nodes, x):
        a, b = nodes[member["i"]], nodes[member["j"]]
        length = math.hypot(b["x"] - a["x"], b["z"] - a["z"])
        t = 0.0 if length == 0 else x / length
        return np.array([a["x"] + (b["x"] - a["x"]) * t, self._frame_y(), a["z"] + (b["z"] - a["z"]) * t], dtype=float)

    def _normal(self, member, nodes):
        a, b = nodes[member["i"]], nodes[member["j"]]
        dx, dz = b["x"] - a["x"], b["z"] - a["z"]
        length = math.hypot(dx, dz)
        return np.array([-dz / length, 0.0, dx / length], dtype=float)

    def _case_factor(self, model, selected_case, load_case):
        if not selected_case:
            return 1.0
        if selected_case in model.get("cases", []):
            return 1.0 if selected_case == load_case else 0.0
        return float((model.get("combinations", {}).get(selected_case, {}) or {}).get(load_case, 0.0))

    @staticmethod
    def _factor_tag(factor, case):
        if abs(factor - 1.0) < 1e-12:
            return f"[{case}]"
        return f"[{factor:.3g}×{case}]"

    def _case_color(self, model, case_name, *, self_weight=False):
        metadata = (model.get("case_metadata", {}) or {}).get(case_name, {})
        load_type = str(metadata.get("type", "")).strip().lower()
        name = str(case_name or "").strip().upper()
        if self_weight:
            return "#6b7280"
        if load_type == "dead" or name.startswith("DL") or name in ("SW", "G"):
            return "#6b7280"
        if load_type == "live" or name.startswith("LL") or name.startswith("L"):
            return "#2563eb"
        if load_type == "wind" or name.startswith("WL") or name.startswith("W"):
            return "#16a34a"
        if load_type in ("seismic", "earthquake") or name.startswith("EQ"):
            return "#dc2626"
        if load_type in ("thermal", "temperature") or name.startswith("TEMP") or name.startswith("T"):
            return "#9333ea"
        palette = ["#0f766e", "#b45309", "#7c3aed", "#be123c", "#0369a1", "#15803d"]
        return palette[sum(ord(ch) for ch in name) % len(palette)]

    def _show_point_loads(self):
        return bool(getattr(getattr(self.panel, "show_point_loads", None), "isChecked", lambda: True)())

    def _show_distributed_loads(self):
        return bool(getattr(getattr(self.panel, "show_distributed_loads", None), "isChecked", lambda: True)())

    def _show_self_weight(self):
        return bool(getattr(getattr(self.panel, "show_self_weight_overlay", None), "isChecked", lambda: True)())

    def _show_load_labels(self):
        return bool(getattr(getattr(self.panel, "show_load_labels", None), "isChecked", lambda: True)())

    def _show_active_load_only(self):
        return bool(getattr(getattr(self.panel, "show_active_load_only", None), "isChecked", lambda: True)())

    def _show_diagram_labels(self):
        return bool(getattr(getattr(self.panel, "show_diagram_labels", None), "isChecked", lambda: True)())

    def _display_factor(self, model, selected_case, load_case):
        if self._show_active_load_only():
            return self._case_factor(model, selected_case, load_case)
        return 1.0

    def case_legend_entries(self, model, selected_case=None, active_only=None):
        if not model:
            return []
        if active_only is None:
            active_only = self._show_active_load_only()
        if selected_case is None:
            selected_case = self.panel.case.currentText() if hasattr(self.panel, "case") else ""

        if active_only:
            if selected_case in model.get("cases", []):
                visible = {selected_case: 1.0}
            else:
                visible = {
                    name: float(factor)
                    for name, factor in (model.get("combinations", {}).get(selected_case, {}) or {}).items()
                    if abs(float(factor)) > 1e-14
                }
        else:
            visible = {name: 1.0 for name in model.get("cases", [])}

        visible_load_cases = set()
        if self._show_point_loads():
            visible_load_cases.update(row.get("case") for row in model.get("point_loads", []) if row.get("case"))
        if self._show_distributed_loads():
            visible_load_cases.update(row.get("case") for row in model.get("distributed_loads", []) if row.get("case"))
        sw_case = model.get("self_weight_case") or "SW"
        if model.get("self_weight") and self._show_self_weight():
            visible_load_cases.add(sw_case)

        entries = []
        for case_name in model.get("cases", []):
            if case_name not in visible or case_name not in visible_load_cases:
                continue
            meta = (model.get("case_metadata", {}) or {}).get(case_name, {})
            label = str(meta.get("type") or case_name)
            factor = float(visible.get(case_name, 1.0))
            entries.append({
                "name": case_name,
                "label": label,
                "description": str(meta.get("description", "")).strip(),
                "factor": factor,
                "color": self._case_color(model, case_name),
            })

        if model.get("self_weight") and self._show_self_weight():
            sw_case = model.get("self_weight_case") or "SW"
            if sw_case in visible:
                entries.append({
                    "name": sw_case,
                    "label": "Self-weight",
                    "description": "Automatic gravity load",
                    "factor": float(visible.get(sw_case, 1.0)),
                    "color": self._case_color(model, sw_case, self_weight=True),
                    "self_weight": True,
                })
        return entries

    def _build(self):
        panel = self.panel
        model = panel.model
        result = panel.result if panel.result_current() else None
        case = panel.case.currentText() if hasattr(panel, "case") else ""
        diagram = panel.diagram.currentText() if hasattr(panel, "diagram") else "Model"
        scale = float(panel.diagram_scale.value()) if hasattr(panel, "diagram_scale") else 1.0
        label_count = int(panel.label_count.value()) if hasattr(panel, "label_count") else 0
        key = (
            panel.revision, panel.result_revision, self._frame_y(), case, diagram, round(scale, 6), label_count,
            self._show_point_loads(), self._show_distributed_loads(), self._show_self_weight(), self._show_load_labels(), self._show_active_load_only(), self._show_diagram_labels(),
        )
        if key == self._key and self._cache is not None:
            return self._cache
        self._key = key
        empty = {"members": [], "nodes": [], "diagram": [], "diagram_labels": [], "reactions": [], "loads": []}
        if not model:
            self._cache = empty
            return self._cache

        nodes = {row["id"]: row for row in model["nodes"]}
        by_member = {row["id"]: row for row in model["members"]}
        members = []
        for member in model["members"]:
            a, b = nodes[member["i"]], nodes[member["j"]]
            members.append((member["id"], np.array([[a["x"], self._frame_y(), a["z"]], [b["x"], self._frame_y(), b["z"]]], dtype=float)))
        node_points = [
            (nid, np.array([row["x"], self._frame_y(), row["z"]], dtype=float), row)
            for nid, row in nodes.items()
        ]

        diagram_lines = []
        diagram_labels = []
        reactions = []
        loads = []
        span = self._span(model)

        # Applied forces/moments: only the selected base case or the factored selected combination.
        if self._show_point_loads():
            for load in model.get("point_loads", []):
                factor = self._display_factor(model, case, load["case"])
                if abs(factor) < 1e-14:
                    continue
                value = float(load["value"]) * factor
                if "node" in load:
                    base = np.array([nodes[load["node"]]["x"], self._frame_y(), nodes[load["node"]]["z"]], dtype=float)
                else:
                    base = self._world_point(by_member[load["member"]], nodes, float(load["x"]))
                tag = self._factor_tag(factor, load["case"])
                color = self._case_color(model, load["case"])
                label = f"{load['direction']} = {value:.4g} kN {tag}" if self._show_load_labels() else ""
                if load["direction"] in ("FX", "FZ"):
                    sign = 1.0 if value >= 0 else -1.0
                    direction = np.array([sign, 0.0, 0.0]) if load["direction"] == "FX" else np.array([0.0, 0.0, sign])
                    tail = base - direction * (0.13 * span)
                    loads.append({
                        "kind": "force", "points": np.array([tail, base]),
                        "label": label, "color": color,
                    })
                else:
                    loads.append({
                        "kind": "moment", "point": base, "sign": 1.0 if value >= 0 else -1.0,
                        "label": f"MY = {value:.4g} kN·m {tag}" if self._show_load_labels() else "", "color": color,
                    })

        if self._show_distributed_loads():
            for load in model.get("distributed_loads", []):
                factor = self._display_factor(model, case, load["case"])
                if abs(factor) < 1e-14:
                    continue
                member = by_member[load["member"]]
                length = math.hypot(
                    nodes[member["j"]]["x"] - nodes[member["i"]]["x"],
                    nodes[member["j"]]["z"] - nodes[member["i"]]["z"],
                )
                x1, x2 = float(load.get("x1", 0.0)), float(load.get("x2", length))
                arrows = []
                tails = []
                for x in np.linspace(x1, x2, 7):
                    base = self._world_point(member, nodes, float(x))
                    t = 0.0 if x2 == x1 else (x - x1) / (x2 - x1)
                    value = (load["w1"] + (load["w2"] - load["w1"]) * t) * factor
                    sign = 1.0 if value >= 0 else -1.0
                    direction = np.array([sign, 0.0, 0.0]) if load["direction"] == "FX" else np.array([0.0, 0.0, sign])
                    # Preserve visible arrow length while keeping direction/sign engineering-correct.
                    tail = base - direction * (0.095 * span)
                    arrows.append(np.array([tail, base]))
                    tails.append(tail)
                w1, w2 = float(load["w1"]) * factor, float(load["w2"]) * factor
                tag = self._factor_tag(factor, load["case"])
                value_text = f"{w1:.4g}" if abs(w1 - w2) < 1e-12 else f"{w1:.4g} → {w2:.4g}"
                loads.append({
                    "kind": "udl", "arrows": arrows, "baseline": np.array(tails),
                    "label": f"{load['direction']} w = {value_text} kN/m {tag}" if self._show_load_labels() else "",
                    "label_point": tails[len(tails) // 2], "color": self._case_color(model, load["case"]),
                })

        # Self-weight is a real engineering load. Show it for its base case and
        # any selected combination that contains the self-weight case.
        if model.get("self_weight", False) and self._show_self_weight():
            sw_case = model.get("self_weight_case")
            if self._show_active_load_only():
                if sw_case:
                    sw_factor = self._case_factor(model, case, sw_case)
                elif case in model.get("cases", []):
                    sw_factor = 1.0
                else:
                    sw_factor = float(sum((model.get("combinations", {}).get(case, {}) or {}).values()))
            else:
                sw_factor = 1.0
            if abs(sw_factor) > 1e-14:
                materials = {row["id"]: row for row in model.get("materials", [])}
                sections = {row["id"]: row for row in model.get("sections", [])}
                for member in model.get("members", []):
                    rho = float(materials[member["material"]].get("rho", 0.0))
                    area = float(sections[member["section"]]["A"])
                    q = -rho * area * sw_factor
                    if abs(q) <= 1e-14:
                        continue
                    length = math.hypot(
                        nodes[member["j"]]["x"] - nodes[member["i"]]["x"],
                        nodes[member["j"]]["z"] - nodes[member["i"]]["z"],
                    )
                    arrows = []
                    tails = []
                    for x in np.linspace(0.0, length, 5):
                        base = self._world_point(member, nodes, float(x))
                        direction = np.array([0.0, 0.0, -1.0])
                        tail = base - direction * (0.06 * span)
                        arrows.append(np.array([tail, base]))
                        tails.append(tail)
                    tag = self._factor_tag(sw_factor, sw_case or "SW")
                    loads.append({
                        "kind": "udl", "arrows": arrows, "baseline": np.array(tails),
                        "label": f"Self-weight FZ w = {q:.4g} kN/m {tag}" if self._show_load_labels() else "",
                        "label_point": tails[1 if len(tails) > 1 else 0],
                        "color": self._case_color(model, sw_case or "SW", self_weight=True),
                    })

        if result and case in result.get("cases", {}):
            case_data = result["cases"][case]
            if diagram in ("N", "V", "M"):
                quantity = diagram
                peak = max((abs(p[quantity]) for mr in case_data["members"].values() for p in mr["plot"]), default=0.0)
                factor = (0.16 * span * scale / peak) if peak > 1e-14 else 0.0
                for mid, mr in case_data["members"].items():
                    member = by_member[mid]
                    normal = self._normal(member, nodes)
                    bases = [self._world_point(member, nodes, p["x"]) for p in mr["plot"]]
                    values = [float(p[quantity]) for p in mr["plot"]]
                    pts = [base + normal * (value * factor) for base, value in zip(bases, values)]
                    diagram_lines.append({
                        "member": mid, "curve": np.array(pts, dtype=float),
                        "baseline": np.array(bases, dtype=float), "values": values, "quantity": quantity,
                    })
                    unit = {"N": "kN", "V": "kN", "M": "kN·m"}[quantity]
                    if self._show_diagram_labels():
                        for row in sample_plot(mr["plot"], mr["L"], label_count):
                            base = self._world_point(member, nodes, row["x"])
                            point = base + normal * (row[quantity] * factor)
                            diagram_labels.append({"point": point, "text": f"{row[quantity]:.4g} {unit}"})
            elif diagram == "Deflection":
                peak = max((abs(p["d"]) for mr in case_data["members"].values() for p in mr["plot"]), default=0.0)
                factor = (0.15 * span * scale / peak) if peak > 1e-14 else 0.0
                for mid, mr in case_data["members"].items():
                    member = by_member[mid]
                    normal = self._normal(member, nodes)
                    pts = []
                    # anaStruct transverse deflection `d` is displayed opposite the
                    # member's positive local normal so a gravity-loaded horizontal
                    # beam visibly sags downward in the engineering viewport.
                    for p in mr["plot"]:
                        base = self._world_point(member, nodes, p["x"])
                        pts.append(base - normal * (p["d"] * factor))
                    diagram_lines.append({"member": mid, "curve": np.array(pts, dtype=float), "quantity": "D"})
                    if self._show_diagram_labels():
                        for row in sample_plot(mr["plot"], mr["L"], label_count):
                            base = self._world_point(member, nodes, row["x"])
                            point = base - normal * (row["d"] * factor)
                            value_mm = row["d"] * 1000.0
                            if abs(value_mm) < 5e-7:
                                value_mm = 0.0
                            diagram_labels.append({"point": point, "text": f"{value_mm:.4g} mm"})
            elif diagram == "Deformed":
                peak = max((math.hypot(p["ux"], p["uz"]) for mr in case_data["members"].values() for p in mr["plot"]), default=0.0)
                factor = (0.15 * span * scale / peak) if peak > 1e-14 else 0.0
                for mid, mr in case_data["members"].items():
                    member = by_member[mid]
                    pts = []
                    for p in mr["plot"]:
                        base = self._world_point(member, nodes, p["x"])
                        pts.append(base + np.array([p["ux"] * factor, 0.0, p["uz"] * factor]))
                    diagram_lines.append({"member": mid, "curve": np.array(pts, dtype=float), "quantity": "D"})
                    if self._show_diagram_labels():
                        for row in sample_plot(mr["plot"], mr["L"], label_count):
                            base = self._world_point(member, nodes, row["x"])
                            point = base + np.array([row["ux"] * factor, 0.0, row["uz"] * factor])
                            value_mm = row["d"] * 1000.0
                            if abs(value_mm) < 5e-7:
                                value_mm = 0.0
                            diagram_labels.append({"point": point, "text": f"{value_mm:.4g} mm"})
            elif diagram == "Reaction":
                peak = max((max(abs(r["Rx"]), abs(r["Rz"])) for r in case_data["nodes"].values()), default=0.0)
                factor = (0.13 * span * scale / peak) if peak > 1e-14 else 0.0
                for nid, reaction in case_data["nodes"].items():
                    base = np.array([nodes[nid]["x"], self._frame_y(), nodes[nid]["z"]], dtype=float)
                    if abs(reaction["Rx"]) > 1e-12:
                        tail = base - np.array([reaction["Rx"] * factor, 0.0, 0.0])
                        reactions.append({"kind": "force", "points": np.array([tail, base]), "label": f"Rx = {reaction['Rx']:.4g} kN"})
                    if abs(reaction["Rz"]) > 1e-12:
                        tail = base - np.array([0.0, 0.0, reaction["Rz"] * factor])
                        reactions.append({"kind": "force", "points": np.array([tail, base]), "label": f"Rz = {reaction['Rz']:.4g} kN"})
                    if abs(reaction["My"]) > 1e-12:
                        reactions.append({"kind": "moment", "point": base, "sign": 1.0 if reaction["My"] >= 0 else -1.0, "label": f"My = {reaction['My']:.4g} kN·m"})

        self._cache = {"members": members, "nodes": node_points, "diagram": diagram_lines, "diagram_labels": diagram_labels, "reactions": reactions, "loads": loads}
        return self._cache

    def _project_one(self, point):
        px, py, front = self.panel.app.world_to_pixels(np.array([point], dtype=float))
        if not front[0]:
            return None
        return QPointF(float(px[0]), float(py[0]))

    def _draw_polyline(self, painter, points, color, width=2):
        if len(points) < 2:
            return
        px, py, front = self.panel.app.world_to_pixels(points)
        painter.setPen(QPen(QColor(color), width))
        for i in range(len(points) - 1):
            if front[i] or front[i + 1]:
                painter.drawLine(QPointF(float(px[i]), float(py[i])), QPointF(float(px[i + 1]), float(py[i + 1])))


    def _draw_signed_fill(self, painter, item):
        baseline = item.get("baseline")
        curve = item.get("curve")
        values = item.get("values") or []
        if baseline is None or curve is None or len(curve) < 2 or len(values) < 2:
            return
        positive = QColor("#3b82f6"); positive.setAlpha(72)
        negative = QColor("#ef4444"); negative.setAlpha(72)
        painter.setPen(QPen(Qt.NoPen))
        for i in range(len(curve) - 1):
            b0, b1 = baseline[i], baseline[i + 1]
            c0, c1 = curve[i], curve[i + 1]
            for t0, t1, sign in signed_interval_parts(values[i], values[i + 1]):
                bb0 = b0 + (b1 - b0) * t0
                bb1 = b0 + (b1 - b0) * t1
                cc0 = c0 + (c1 - c0) * t0
                cc1 = c0 + (c1 - c0) * t1
                world = np.array([bb0, cc0, cc1, bb1], dtype=float)
                px, py, front = self.panel.app.world_to_pixels(world)
                if not any(bool(v) for v in front):
                    continue
                painter.setBrush(QBrush(positive if sign >= 0 else negative))
                painter.drawPolygon(QPolygonF([QPointF(float(px[j]), float(py[j])) for j in range(4)]))

    def _draw_arrow(self, painter, points, color, label="", label_offset=(6.0, -6.0), width=2, label_priority=60):
        px, py, front = self.panel.app.world_to_pixels(points)
        if not (front[0] or front[-1]):
            return
        a = QPointF(float(px[0]), float(py[0])); b = QPointF(float(px[-1]), float(py[-1]))
        painter.setPen(QPen(QColor(color), width)); painter.setBrush(QBrush(QColor(color)))
        painter.drawLine(a, b)
        dx, dy = b.x() - a.x(), b.y() - a.y()
        length = math.hypot(dx, dy)
        if length > 1e-6:
            ux, uy = dx / length, dy / length
            nx, ny = -uy, ux
            size = 8.0
            p1 = QPointF(b.x() - ux * size + nx * size * 0.48, b.y() - uy * size + ny * size * 0.48)
            p2 = QPointF(b.x() - ux * size - nx * size * 0.48, b.y() - uy * size - ny * size * 0.48)
            painter.drawPolygon(QPolygonF([b, p1, p2]))
        if label:
            self._labels.add(a, label, color, priority=label_priority)

    def _draw_moment(self, painter, world, sign, color, label, label_priority=65):
        p = self._project_one(world)
        if p is None:
            return
        radius = 17.0
        rect = QRectF(p.x() - radius, p.y() - radius, radius * 2, radius * 2)
        painter.setPen(QPen(QColor(color), 2)); painter.setBrush(QBrush(QColor(color)))
        start = 35 * 16 if sign >= 0 else 145 * 16
        span = 285 * 16 if sign >= 0 else -285 * 16
        painter.drawArc(rect, start, span)
        # Arrow head near the arc end; visual sign follows the arc direction.
        angle = math.radians(320 if sign >= 0 else 220)
        tip = QPointF(p.x() + radius * math.cos(angle), p.y() - radius * math.sin(angle))
        tangent = angle - (math.pi / 2 if sign >= 0 else -math.pi / 2)
        ux, uy = math.cos(tangent), -math.sin(tangent)
        nx, ny = -uy, ux
        size = 7.0
        p1 = QPointF(tip.x() - ux * size + nx * size * 0.45, tip.y() - uy * size + ny * size * 0.45)
        p2 = QPointF(tip.x() - ux * size - nx * size * 0.45, tip.y() - uy * size - ny * size * 0.45)
        painter.drawPolygon(QPolygonF([tip, p1, p2]))
        self._labels.add(p, label, color, priority=label_priority)

    def _draw_support(self, painter, point, node, selected=False):
        p = self._project_one(point)
        if p is None:
            return
        support = node.get("support", "Free")
        color = QColor("#d88920" if selected else "#34495e")
        painter.setPen(QPen(color, 2)); painter.setBrush(QBrush())
        painter.drawEllipse(p, 4.5, 4.5)
        if support == "Free":
            return
        x, y = p.x(), p.y()
        if support == "Fixed":
            painter.drawLine(QPointF(x - 10, y + 6), QPointF(x + 10, y + 6))
            for dx in (-8, -4, 0, 4, 8):
                painter.drawLine(QPointF(x + dx, y + 6), QPointF(x + dx - 5, y + 13))
        elif support in ("Pin", "Roller"):
            triangle = QPolygonF([QPointF(x, y + 5), QPointF(x - 10, y + 18), QPointF(x + 10, y + 18)])
            painter.drawPolygon(triangle)
            if support == "Roller":
                painter.drawEllipse(QPointF(x - 5, y + 22), 3.0, 3.0)
                painter.drawEllipse(QPointF(x + 5, y + 22), 3.0, 3.0)
                painter.drawLine(QPointF(x - 12, y + 27), QPointF(x + 12, y + 27))
        elif support == "RollerX":
            triangle = QPolygonF([QPointF(x + 5, y), QPointF(x + 18, y - 10), QPointF(x + 18, y + 10)])
            painter.drawPolygon(triangle)
            painter.drawEllipse(QPointF(x + 22, y - 5), 3.0, 3.0)
            painter.drawEllipse(QPointF(x + 22, y + 5), 3.0, 3.0)
            painter.drawLine(QPointF(x + 27, y - 12), QPointF(x + 27, y + 12))
        elif support == "Spring":
            path = QPainterPath(QPointF(x, y + 5))
            path.lineTo(x, y + 9)
            for i, dx in enumerate((-5, 5, -5, 5, -5, 5)):
                path.lineTo(x + dx, y + 12 + i * 4)
            path.lineTo(x, y + 38)
            painter.drawPath(path)
            painter.drawLine(QPointF(x - 11, y + 38), QPointF(x + 11, y + 38))
            springs = node.get("springs", {}) or {}
            labels = []
            for dof, unit in (("UX", "kN/m"), ("UZ", "kN/m"), ("RY", "kN·m/rad")):
                if dof in springs:
                    labels.append(f"k{dof[1:].lower()}={springs[dof]:.4g} {unit}")
            if labels:
                self._labels.add(QPointF(x + 10, y + 36), ", ".join(labels), "#34495e", priority=75)

    def _auto_label_layout(self):
        checkbox = getattr(self.panel, "auto_label_layout", None)
        return True if checkbox is None else bool(checkbox.isChecked())

    def paint(self, viewport, painter):
        overlay_toggle = getattr(self.panel, "show_analytical_overlay", None)
        if overlay_toggle is not None and not overlay_toggle.isChecked():
            return
        self._labels = LabelLayout()
        cache = self._build()
        selected = self.panel.selected_item

        for mid, points in cache["members"]:
            color = "#d88920" if selected == "member:" + mid else "#5c6873"
            self._draw_polyline(painter, points, color, 3 if selected == "member:" + mid else 2)

        marker_toggle = getattr(self.panel, "show_alignment_markers", None)
        if marker_toggle is not None and marker_toggle.isChecked():
            placement = getattr(self.panel, "factory_placement", {}) or {}
            for coords in placement.get("markers", []):
                if len(coords) != 3:
                    continue
                pos = self._project_one(np.array(coords, dtype=float))
                if pos is not None:
                    painter.setPen(QPen(QColor("#00a7bf"), 2))
                    painter.setBrush(Qt.BrushStyle.NoBrush)
                    painter.drawEllipse(pos, 5.0, 5.0)

        for nid, point, node in cache["nodes"]:
            self._draw_support(painter, point, node, selected == "node:" + nid)

        # Applied actions are blue and always carry engineering values/units.
        for item in cache.get("loads", []):
            color = item.get("color", "#2b7dbd")
            if item["kind"] == "force":
                self._draw_arrow(painter, item["points"], color, item["label"], width=2)
            elif item["kind"] == "moment":
                self._draw_moment(painter, item["point"], item["sign"], color, item["label"])
            elif item["kind"] == "udl":
                self._draw_polyline(painter, item["baseline"], color, 1)
                for arrow in item["arrows"]:
                    self._draw_arrow(painter, arrow, color, width=1)
                label_point = self._project_one(item["label_point"])
                if label_point is not None and item.get("label"):
                    painter.setPen(QPen(QColor(color), 1))
                    self._labels.add(label_point, item["label"], color, priority=50)

        for item in cache["diagram"]:
            quantity = item.get("quantity", "D")
            if quantity in ("N", "V", "M"):
                self._draw_signed_fill(painter, item)
            color = {"N": "#244a7c", "V": "#236b48", "M": "#8f3030", "D": "#8b5cb8"}.get(quantity, "#8b5cb8")
            self._draw_polyline(painter, item["curve"], color, 2)

        for label in cache.get("diagram_labels", []):
            p = self._project_one(label["point"])
            if p is not None:
                painter.setPen(QPen(QColor("#1f2933"), 1))
                self._labels.add(p, label["text"], "#1f2933", priority=30)

        for item in cache["reactions"]:
            if item["kind"] == "force":
                self._draw_arrow(painter, item["points"], "#cf7f20", item["label"], width=2, label_priority=100)
            else:
                self._draw_moment(painter, item["point"], item["sign"], "#cf7f20", item["label"], label_priority=100)

        if not self.panel.show_ids.isChecked() and not self.panel.show_values.isChecked():
            self._labels.paint(painter, avoid_collisions=self._auto_label_layout())
            return
        model = self.panel.model
        if not model:
            self._labels.paint(painter, avoid_collisions=self._auto_label_layout())
            return
        nodes = {row["id"]: row for row in model["nodes"]}
        painter.setPen(QPen(QColor("#1f2933"), 1))

        if self.panel.show_ids.isChecked():
            pts = np.array([[row["x"], self._frame_y(), row["z"]] for row in model["nodes"]], dtype=float)
            px, py, front = self.panel.app.world_to_pixels(pts)
            for i, row in enumerate(model["nodes"]):
                if front[i]:
                    self._labels.add(QPointF(float(px[i]), float(py[i])), row["id"], "#34495e", priority=45)
            for member in model["members"]:
                a, b = nodes[member["i"]], nodes[member["j"]]
                pt = np.array([[(a["x"] + b["x"]) / 2.0, self._frame_y(), (a["z"] + b["z"]) / 2.0]], dtype=float)
                mx, my, mf = self.panel.app.world_to_pixels(pt)
                if mf[0]:
                    self._labels.add(QPointF(float(mx[0]), float(my[0])), member["id"], "#34495e", priority=42)

        if self.panel.show_values.isChecked() and self.panel.result_current():
            case = self.panel.case.currentText()
            diagram = self.panel.diagram.currentText()
            if case in self.panel.result.get("cases", {}) and diagram in ("N", "V", "M", "Deflection"):
                quantity = {"Deflection": "d"}.get(diagram, diagram)
                unit = {"N": "kN", "V": "kN", "M": "kN·m", "d": "mm"}[quantity]
                by_id = {m["id"]: m for m in model["members"]}
                for mid, mr in self.panel.result["cases"][case]["members"].items():
                    member = by_id[mid]
                    extrema = mr["extrema"][quantity]
                    for kind in ("min", "max"):
                        row = extrema[kind]
                        pt = np.array([self._world_point(member, nodes, row["x"])], dtype=float)
                        x, y, front = self.panel.app.world_to_pixels(pt)
                        if front[0]:
                            value = row["value"] * 1000.0 if quantity == "d" else row["value"]
                            if abs(value) < 5e-7:
                                value = 0.0
                            self._labels.add(
                                QPointF(float(x[0]), float(y[0])),
                                f"{value:.4g} {unit}", "#202a35", priority=85,
                            )

        self._labels.paint(painter, avoid_collisions=self._auto_label_layout())

from __future__ import annotations
import math
import numpy as np

from .diagram_utils import interpolate_plot


def _closest_parameter(px, py, a, b):
    dx, dy = b[0] - a[0], b[1] - a[1]
    denom = dx * dx + dy * dy
    if denom <= 1e-12:
        return 0.0, math.hypot(px - a[0], py - a[1])
    t = max(0.0, min(1.0, ((px - a[0]) * dx + (py - a[1]) * dy) / denom))
    qx, qy = a[0] + t * dx, a[1] + t * dy
    return t, math.hypot(px - qx, py - qy)


def _distance_to_segment(px, py, a, b):
    return _closest_parameter(px, py, a, b)[1]


def pick_item(app, model, px, py, tolerance=9.0, frame_y=0.0):
    if not model:
        return None
    nodes = {row["id"]: row for row in model["nodes"]}
    node_ids = list(nodes)
    pts = np.array([[nodes[n]["x"], frame_y, nodes[n]["z"]] for n in node_ids], dtype=float)
    sx, sy, front = app.world_to_pixels(pts)
    best = None
    for i, nid in enumerate(node_ids):
        if not front[i]:
            continue
        distance = math.hypot(px - float(sx[i]), py - float(sy[i]))
        if distance <= tolerance and (best is None or distance < best[0]):
            best = (distance, "node:" + nid)
    if best is not None:
        return best[1]

    hits = []
    for member in model["members"]:
        a, b = nodes[member["i"]], nodes[member["j"]]
        points = np.array([[a["x"], frame_y, a["z"]], [b["x"], frame_y, b["z"]]], dtype=float)
        mx, my, mf = app.world_to_pixels(points)
        if not bool(mf[0]) and not bool(mf[1]):
            continue
        distance = _distance_to_segment(px, py, (float(mx[0]), float(my[0])), (float(mx[1]), float(my[1])))
        if distance <= tolerance:
            hits.append((distance, "member:" + member["id"]))
    return min(hits, key=lambda row: row[0])[1] if hits else None


def hover_member_data(app, model, result, case, px, py, tolerance=13.0, frame_y=0.0):
    """Return cached member-result data nearest a viewport pixel, or None."""
    if not model or not result or case not in result.get("cases", {}):
        return None
    nodes = {row["id"]: row for row in model["nodes"]}
    case_data = result["cases"][case]
    best = None
    for member in model.get("members", []):
        mr = case_data.get("members", {}).get(member["id"])
        if not mr:
            continue
        a, b = nodes[member["i"]], nodes[member["j"]]
        world = np.array([[a["x"], frame_y, a["z"]], [b["x"], frame_y, b["z"]]], dtype=float)
        sx, sy, front = app.world_to_pixels(world)
        if not bool(front[0]) and not bool(front[1]):
            continue
        t, distance = _closest_parameter(px, py, (float(sx[0]), float(sy[0])), (float(sx[1]), float(sy[1])))
        if distance > tolerance or (best is not None and distance >= best[0]):
            continue
        length = float(mr.get("L", math.hypot(b["x"] - a["x"], b["z"] - a["z"])))
        x = t * length
        values = interpolate_plot(mr.get("plot", []), x)
        wx = a["x"] + t * (b["x"] - a["x"])
        wz = a["z"] + t * (b["z"] - a["z"])
        label = (
            f"{member['id']} @ {x:.3f} m | "
            f"N = {values['N']:.4g} kN | V = {values['V']:.4g} kN | "
            f"M = {values['M']:.4g} kN·m | d = {values['d'] * 1000.0:.4g} mm [{case}]"
        )
        best = {"distance": distance, "member": member["id"], "x": x, "values": values, "world": (wx, frame_y, wz), "label": label}
    return best


def internal_force_hover(app, model, result, case, px, py, tolerance=13.0, frame_y=0.0):
    """Return a native SnapResult for tools that use the IngeTrazo snap pipeline."""
    best = hover_member_data(app, model, result, case, px, py, tolerance=tolerance, frame_y=frame_y)
    if best is None:
        return None
    from PySide6.QtGui import QVector3D
    from core.snap import SnapResult
    wx, wy, wz = best["world"]
    return SnapResult(QVector3D(float(wx), float(wy), float(wz)), "reference", (0.15, 0.55, 0.95), label=best["label"])

